from pathlib import Path

main=Path('lib/main_online.dart')
s=main.read_text()
s=s.replace("import 'package:connectivity_plus/connectivity_plus.dart';", "import 'package:connectivity_plus/connectivity_plus.dart';\nimport 'package:crypto/crypto.dart' as crypto;",1)

# OfflineStore: user identity, cached credentials and local logout state.
anchor="""  int? get lastTankId => _intOrNull(_state['last_tank_id']);\n\n  bool _fuelingRpc(String rpc) => rpc.startsWith('rca_record_fueling');\n"""
insert="""  int? get lastTankId => _intOrNull(_state['last_tank_id']);\n  String? get activeUserIdV62 { final v='${_state['active_user_id_v62']??''}'.trim(); return v.isEmpty?Supabase.instance.client.auth.currentUser?.id:v; }\n  bool get appLoggedOutV62 => _state['app_logged_out_v62']==true;\n  Map<String,dynamic> get _offlineUsersV62 => _state['offline_users_v62'] is Map ? _map(_state['offline_users_v62']) : <String,dynamic>{};\n  String _offlineKeyV62(String username)=>username.trim().toLowerCase();\n  String _offlineHashV62(String username,String password){\n    final device='${_state['device_id_v39']??'rc-device'}';\n    return crypto.sha256.convert(utf8.encode('$device|${_offlineKeyV62(username)}|$password')).toString();\n  }\n  Future<void> cacheOfflineLoginV62(String username,String password,Map<String,dynamic> profile) async {\n    final key=_offlineKeyV62(username);\n    final users=_offlineUsersV62;\n    final uid='${profile['user_id']??profile['id']??Supabase.instance.client.auth.currentUser?.id??''}'.trim();\n    users[key]=<String,dynamic>{'hash':_offlineHashV62(username,password),'profile':profile,'user_id':uid,'updated_at':DateTime.now().toUtc().toIso8601String()};\n    _state['offline_users_v62']=users;_state['profile']=profile;_state['active_user_id_v62']=uid;_state['app_logged_out_v62']=false;await _persist();\n  }\n  Future<Map<String,dynamic>> offlineLoginV62(String username,String password) async {\n    final key=_offlineKeyV62(username),users=_offlineUsersV62;final raw=users[key];\n    if(raw is! Map)throw Exception('Este usuário ainda não foi habilitado para acesso offline neste aparelho. Conecte-se à internet e entre uma vez.');\n    final item=_map(raw);if('${item['hash']??''}'!=_offlineHashV62(username,password))throw Exception('Usuário ou senha/PIN inválidos.');\n    final p=_map(item['profile']);if(p.isEmpty)throw Exception('Dados offline deste usuário não estão disponíveis.');\n    _state['profile']=p;_state['active_user_id_v62']='${item['user_id']??p['user_id']??p['id']??''}';_state['app_logged_out_v62']=false;await _persist();return p;\n  }\n  Future<void> markAppLoggedOutV62() async {_state['app_logged_out_v62']=true;_state.remove('active_user_id_v62');_state.remove('profile');await _persist();}\n  Future<void> markAppLoggedInV62([String? uid]) async {_state['app_logged_out_v62']=false;if(uid!=null&&uid.isNotEmpty)_state['active_user_id_v62']=uid;await _persist();}\n  Future<void> queueOfflineLogoutV62({required String? sessionId,required int? tankId,required DateTime occurredAt}) async {\n    final owner=activeUserIdV62;if(owner==null||owner.isEmpty)throw Exception('Não foi possível identificar o usuário para registrar a saída offline.');\n    final queue=_queue;queue.add(<String,dynamic>{'id':'${DateTime.now().microsecondsSinceEpoch}','rpc':'rca_offline_logout_v62','params':{'p_session_id':sessionId,'p_tank_id':tankId,'p_occurred_at':occurredAt.toUtc().toIso8601String()},'created_at':occurredAt.toUtc().toIso8601String(),'user_id':owner});_state['queue']=queue;pendingCount.value=queue.length;await _persist();syncRevision.value++;\n  }\n  Future<void> queueOfflineReleaseV62({required int? tankId,required DateTime occurredAt}) async {\n    final owner=activeUserIdV62;if(owner==null||owner.isEmpty)return;final queue=_queue;queue.add(<String,dynamic>{'id':'${DateTime.now().microsecondsSinceEpoch}','rpc':'rca_offline_release_unit_v62','params':{'p_tank_id':tankId,'p_occurred_at':occurredAt.toUtc().toIso8601String()},'created_at':occurredAt.toUtc().toIso8601String(),'user_id':owner});_state['queue']=queue;pendingCount.value=queue.length;await _persist();syncRevision.value++;\n  }\n\n  bool _fuelingRpc(String rpc) => rpc.startsWith('rca_record_fueling');\n"""
assert anchor in s
s=s.replace(anchor,insert,1)

s=s.replace("final uid=Supabase.instance.client.auth.currentUser?.id;\n    final ref=cachedReferenceData;", "final uid=activeUserIdV62;\n    final ref=cachedReferenceData;",1)
s=s.replace("final uid=(Supabase.instance.client.auth.currentUser?.id??'00000000-0000-0000-0000-000000000000').replaceAll('-','');", "final uid=(activeUserIdV62??'00000000-0000-0000-0000-000000000000').replaceAll('-','');",1)
s=s.replace("'user_id': Supabase.instance.client.auth.currentUser?.id,", "'user_id': activeUserIdV62,",1)

# Ao reconectar após login offline, cria uma nova sessão de app antes de sincronizar a fila.
old_sync="""    final uid=Supabase.instance.client.auth.currentUser?.id;\n    if(uid==null)return;\n    _syncing = true;\n    try {\n      final snapshot = List<Map<String, dynamic>>.from(_queue);\n"""
new_sync="""    final uid=Supabase.instance.client.auth.currentUser?.id;\n    if(uid==null)return;\n    _syncing = true;\n    try {\n      if(!appLoggedOutV62&&activeUserIdV62==uid&&appSessionIdV30==null){\n        try{final sid=await ensureAppSessionIdV30(renew:true);final dev=await _stableDeviceIdV42();await Supabase.instance.client.rpc('rca_session_claim_v42',params:{'p_session_id':sid,'p_device_id':dev,'p_explicit_login':false});}catch(e){if(_isNetworkError(e)){markOffline();return;}}\n      }\n      final snapshot = List<Map<String, dynamic>>.from(_queue);\n"""
assert old_sync in s
s=s.replace(old_sync,new_sync,1)

# AuthGate: restore/login/logout offline.
old_restore="""  Future<void> _restore() async {\n    final cached=offlineStore.cachedProfile;\n    if(Supabase.instance.client.auth.currentSession==null){if(!offlineStore.online.value&&cached!=null){if(mounted)setState((){profile=cached;loading=false;});}else if(mounted)setState(()=>loading=false);return;}\n    try{if(offlineStore.online.value){final claim=await _claimSessionV42(explicitLogin:false);if(claim['ok']!=true){await _forcedLocalLogoutV30('${claim['message']??'Sua sessão não está mais ativa. Entre novamente para continuar.'}');return;}}final p=await api.profile();offlineStore.markOnline();await offlineStore.cacheProfile(p);if(mounted)setState((){profile=p;loading=false;});_startSessionGuardV30();unawaited(offlineStore.syncPending());}\n    catch(e){if(_isNetworkError(e)&&cached!=null){offlineStore.markOffline();if(mounted)setState((){profile=cached;loading=false;});}else{await _forcedLocalLogoutV30(_friendlyError(e));}}\n  }\n"""
new_restore="""  Future<void> _restore() async {\n    final cached=offlineStore.cachedProfile;\n    if(offlineStore.appLoggedOutV62){if(mounted)setState(()=>loading=false);return;}\n    if(Supabase.instance.client.auth.currentSession==null){if(!offlineStore.online.value&&cached!=null){if(mounted)setState((){profile=cached;loading=false;});}else if(mounted)setState(()=>loading=false);return;}\n    try{if(offlineStore.online.value){final claim=await _claimSessionV42(explicitLogin:false);if(claim['ok']!=true){await _forcedLocalLogoutV30('${claim['message']??'Sua sessão não está mais ativa. Entre novamente para continuar.'}');return;}}final p=await api.profile();offlineStore.markOnline();await offlineStore.cacheProfile(p);await offlineStore.markAppLoggedInV62(Supabase.instance.client.auth.currentUser?.id);if(mounted)setState((){profile=p;loading=false;});_startSessionGuardV30();unawaited(offlineStore.syncPending());}\n    catch(e){if(_isNetworkError(e)&&cached!=null){offlineStore.markOffline();if(mounted)setState((){profile=cached;loading=false;});}else{await _forcedLocalLogoutV30(_friendlyError(e));}}\n  }\n"""
assert old_restore in s
s=s.replace(old_restore,new_restore,1)

login_start=s.index("  Future<void> _login(String username,String password) async {")
login_end=s.index("  Future<void> _logout() async {",login_start)
new_login="""  Future<void> _login(String username,String password) async {\n    setState((){loading=true;error=null;});\n    final client=Supabase.instance.client;\n    final normalized=username.trim().toLowerCase();\n    final testUsername=normalized=='motorista'?'motorista1':normalized;\n    if(!offlineStore.online.value){\n      try{final p=await offlineStore.offlineLoginV62(normalized,password);if(mounted)setState((){profile=p;loading=false;error=null;});return;}\n      catch(e){if(mounted)setState((){loading=false;error=_friendlyError(e);});return;}\n    }\n    try{\n      final loginPassword=_authPasswordForLogin(password);\n      var signedIn=false;\n      if(normalized.contains('@')){await client.auth.signInWithPassword(email:normalized,password:loginPassword);signedIn=true;}\n      else if(normalized=='admin'||normalized=='adminfuel'){\n        for(final email in const ['marinhrodrigo@gmail.com','adminfuel@rccombustivel.app']){try{await client.auth.signInWithPassword(email:email,password:loginPassword);signedIn=true;break;}catch(_){}}\n        if(!signedIn)throw Exception('Usuário ou senha inválidos.');\n      }else{\n        try{await client.auth.signInWithPassword(email:'$testUsername@rccombustivel.app',password:loginPassword);signedIn=true;}catch(_){}\n        if(!signedIn&&const {'operador','motorista','motorista1','motorista2'}.contains(normalized)){\n          final res=await client.functions.invoke('fuel-test-login',body:{'username':testUsername,'password':password});final data=_map(res.data);\n          if(res.status>=200&&res.status<300&&data['refresh_token']!=null){await client.auth.setSession('${data['refresh_token']}');signedIn=true;}else{throw Exception('Usuário ou senha inválidos.');}\n        }\n        if(!signedIn){await client.auth.signInWithPassword(email:'$normalized@rcmanutencao.app',password:loginPassword);signedIn=true;}\n      }\n      final claim=await _claimSessionV42(explicitLogin:true);if(claim['ok']!=true)throw Exception('${claim['message']??'Não foi possível registrar esta sessão.'}');\n      final p=await api.profile();offlineStore.markOnline();await offlineStore.cacheProfile(p);await offlineStore.cacheOfflineLoginV62(normalized,password,p);\n      if(mounted)setState((){profile=p;loading=false;});_startSessionGuardV30();unawaited(offlineStore.syncPending());\n    }catch(e){\n      if(_isNetworkError(e)){\n        offlineStore.markOffline();\n        try{final p=await offlineStore.offlineLoginV62(normalized,password);if(mounted)setState((){profile=p;loading=false;error=null;});return;}catch(_){}\n      }\n      _sessionGuardV30?.cancel();await offlineStore.clearAppSessionIdV30();try{await client.auth.signOut();}catch(_){}\n      if(mounted)setState((){loading=false;error=_friendlyError(e);});\n    }\n  }\n"""
s=s[:login_start]+new_login+s[login_end:]

old_logout="""  Future<void> _logout() async {if(!offlineStore.online.value)throw Exception('Conecte-se à internet para sair e liberar sua unidade.');final id=offlineStore.appSessionIdV30;if(id!=null)await api.logoutV30(id);_sessionGuardV30?.cancel();if(mounted)setState(()=>profile=null);await offlineStore.clearProfile();await offlineStore.setLastTankId(null);await offlineStore.clearAppSessionIdV30();await Supabase.instance.client.auth.signOut(scope:SignOutScope.local).timeout(const Duration(seconds:2));}\n"""
new_logout="""  Future<void> _logout() async {\n    final id=offlineStore.appSessionIdV30;final tankId=offlineStore.lastTankId;final occurred=DateTime.now();_sessionGuardV30?.cancel();\n    if(!offlineStore.online.value){\n      await offlineStore.queueOfflineLogoutV62(sessionId:id,tankId:tankId,occurredAt:occurred);\n      await offlineStore.setLastTankId(null);await offlineStore.clearAppSessionIdV30();await offlineStore.markAppLoggedOutV62();\n      if(mounted)setState(()=>profile=null);\n      return;\n    }\n    if(id!=null)await api.logoutV30(id);if(mounted)setState(()=>profile=null);await offlineStore.clearProfile();await offlineStore.setLastTankId(null);await offlineStore.clearAppSessionIdV30();await offlineStore.markAppLoggedOutV62();await Supabase.instance.client.auth.signOut(scope:SignOutScope.local).timeout(const Duration(seconds:2));\n  }\n"""
assert old_logout in s
s=s.replace(old_logout,new_logout,1)
s=s.replace("Future<void> _forcedLocalLogoutV30(String message) async {_sessionGuardV30?.cancel();await offlineStore.clearProfile();await offlineStore.setLastTankId(null);await offlineStore.clearAppSessionIdV30();", "Future<void> _forcedLocalLogoutV30(String message) async {_sessionGuardV30?.cancel();await offlineStore.clearProfile();await offlineStore.setLastTankId(null);await offlineStore.clearAppSessionIdV30();await offlineStore.markAppLoggedOutV62();",1)
s=s.replace("if (_isNetworkError(e)) return 'Sem conexão com a internet.';", "if (_isNetworkError(e)) return 'Sem conexão com a internet. Use um usuário que já tenha acessado este aparelho online para entrar offline.';",1)
s=s.replace("  if (s.contains('Conecte-se à internet para sair')) return 'Conecte-se à internet para sair e liberar sua unidade.';\n", "",1)
s=s.replace("child: Text('v61'","child: Text('v62'",1)
main.write_text(s)

v30=Path('lib/v30_features.dart');t=v30.read_text()
api_anchor="""  Future<Map<String,dynamic>> logoutV30(String id) async => _map(await client.rpc('rca_logout_v30',params:{'p_session_id':id}));\n"""
api_insert=api_anchor+"""  Future<Map<String,dynamic>> offlineLogoutV62(String? id,int? tankId,DateTime occurredAt) async => _map(await client.rpc('rca_offline_logout_v62',params:{'p_session_id':id,'p_tank_id':tankId,'p_occurred_at':occurredAt.toUtc().toIso8601String()}));\n  Future<Map<String,dynamic>> offlineReleaseV62(int? tankId,DateTime occurredAt) async => _map(await client.rpc('rca_offline_release_unit_v62',params:{'p_tank_id':tankId,'p_occurred_at':occurredAt.toUtc().toIso8601String()}));\n"""
assert api_anchor in t
t=t.replace(api_anchor,api_insert,1)
v30.write_text(t)

