u=u.replace("""      if(!offlineStore.online.value){\n        final cached=offlineStore.cachedReferenceData;\n        if(mounted)setState((){ref=cached;loading=false;error=null;});\n        return;\n      }\n""", """      if(!offlineStore.online.value){\n        final cached=offlineStore.cachedReferenceData;final tid=offlineStore.lastTankId;Map<String,dynamic> mine={};\n        for(final x in _sortedFuelUnits(cached?['tanks'])){if(_intOrNull(x['id'])==tid){mine={'tank_id':tid,'unit_code':x['code'],'unit_name':x['name'],'tank_type':x['tank_type']};break;}}\n        if(mounted)setState((){ref=cached;currentUnit=mine;statuses=[];loading=false;error=cached==null?'Conecte-se à internet uma vez para baixar os dados necessários ao modo offline.':null;});\n        return;\n      }\n""",1)
u=u.replace("""    if(!offlineStore.online.value){\n      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Conecte-se à internet para selecionar ou trocar de unidade.')));\n      return null;\n    }\n    try{statuses=await api.unitStatusV30();}catch(_){}\n""", """    if(offlineStore.online.value){try{statuses=await api.unitStatusV30();}catch(_){}}else{statuses=[];}\n""",1)
u=u.replace("""    if(!offlineStore.online.value){\n      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Conecte-se à internet para selecionar ou trocar de unidade.')));\n      return false;\n    }\n    try{\n""", """    if(!offlineStore.online.value){\n      await offlineStore.setLastTankId(id);\n      if(mounted)setState(()=>currentUnit={'tank_id':id,'unit_code':tank['code'],'unit_name':tank['name'],'tank_type':tank['tank_type']});\n      if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Unidade selecionada offline. A validação será feita quando a internet voltar.')));\n      return true;\n    }\n    try{\n""",1)
old_release="""    if(!offlineStore.online.value){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Conecte-se à internet para liberar a unidade.')));return;}\n"""
new_release="""    if(!offlineStore.online.value){\n      await offlineStore.queueOfflineReleaseV62(tankId:id,occurredAt:DateTime.now());await offlineStore.setLastTankId(null);if(mounted)setState(()=>currentUnit={});\n      if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Unidade liberada offline. A liberação será sincronizada quando a internet voltar.')));return;\n    }\n"""
